-- ============================================================
-- 健康食品推荐系统 数据库初始化脚本
-- 数据来源:GB 2760-2024 食品安全国家标准 食品添加剂使用标准
-- 对应论文 §3.3.2 数据库逻辑设计
-- ============================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- 创建数据库(如不存在)
CREATE DATABASE IF NOT EXISTS `health_food` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `health_food`;

-- ----------------------------
-- 表 1:用户表(论文表3-1)
-- ----------------------------
DROP TABLE IF EXISTS `user`;
CREATE TABLE `user` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '用户ID',
  `username` VARCHAR(50) NOT NULL COMMENT '用户名',
  `password` VARCHAR(255) NOT NULL COMMENT '密码(BCrypt加密存储)',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `health_goal` VARCHAR(20) NULL COMMENT '健康目标:减脂/增肌/控糖/控压/通用',
  `chronic_diseases` VARCHAR(200) NULL COMMENT '慢性病(逗号分隔)',
  `allergens` VARCHAR(200) NULL COMMENT '过敏原(逗号分隔)',
  `role` VARCHAR(20) NOT NULL DEFAULT 'user' COMMENT '角色:user=普通用户/admin=管理员',
  `status` TINYINT(1) NOT NULL DEFAULT 1 COMMENT '账号状态:1=启用/0=禁用',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_username` (`username`),
  KEY `idx_role` (`role`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户表';

-- ----------------------------
-- 表 2:历史记录表(论文表3-2)
-- ----------------------------
DROP TABLE IF EXISTS `history_record`;
CREATE TABLE `history_record` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `user_id` BIGINT NOT NULL COMMENT '用户ID',
  `product_name` VARCHAR(200) DEFAULT NULL COMMENT '产品名称',
  `category` VARCHAR(100) DEFAULT NULL COMMENT '食品品类，用于同品类对比',
  `result_json` TEXT COMMENT '识别结果JSON(完整结构化数据)',
  `image_url` VARCHAR(500) DEFAULT NULL COMMENT '图片存储URL',
  `is_favorite` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '是否收藏:0未收藏,1已收藏',
  `health_score` TINYINT UNSIGNED NULL COMMENT '健康评分 0-100（识别入库时计算；NULL=未计算/老数据）',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_create_time` (`create_time`),
  CONSTRAINT `fk_history_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='历史记录表';

-- ----------------------------
-- 表 3:添加剂知识表(论文表3-3)
-- 注:cns_no/ins_no 为新增辅助字段,用于精确匹配,论文未要求可作扩展说明
-- ----------------------------
DROP TABLE IF EXISTS `additive_knowledge`;
CREATE TABLE `additive_knowledge` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '添加剂ID',
  `additive_name` VARCHAR(200) NOT NULL COMMENT '添加剂中文名称',
  `english_name` VARCHAR(300) DEFAULT NULL COMMENT '英文名称',
  `cns_no` VARCHAR(50) DEFAULT NULL COMMENT 'CNS编号(中国添加剂编码)',
  `ins_no` VARCHAR(50) DEFAULT NULL COMMENT 'INS编号(国际编码)',
  `function_category` VARCHAR(200) DEFAULT NULL COMMENT '功能类别',
  `safety_desc` VARCHAR(500) DEFAULT NULL COMMENT '安全性通俗化说明',
  `usage_scope` VARCHAR(200) DEFAULT NULL COMMENT '使用范围(摘要)',
  `max_dosage` VARCHAR(100) DEFAULT NULL COMMENT '最大添加量(摘要)',
  `disease_contraindication` VARCHAR(200) DEFAULT NULL COMMENT '疾病禁忌',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_additive_name` (`additive_name`),
  KEY `idx_cns` (`cns_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='添加剂知识表';

-- ----------------------------
-- 表 4:食品分类字典表(扩展,GB 2760-2024 食品分类系统)
-- ----------------------------
DROP TABLE IF EXISTS `food_category`;
CREATE TABLE `food_category` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '分类ID',
  `category_code` VARCHAR(20) NOT NULL COMMENT '食品分类号(如01.01.01)',
  `category_name` VARCHAR(300) NOT NULL COMMENT '食品名称',
  `parent_code` VARCHAR(20) DEFAULT NULL COMMENT '上级分类号',
  `remark` VARCHAR(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_category_code` (`category_code`),
  KEY `idx_parent_code` (`parent_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='食品分类字典表';

-- ----------------------------
-- 表 5:添加剂×食品分类 限量明细表(扩展,GB 2760-2024核心数据)
-- ----------------------------
DROP TABLE IF EXISTS `additive_food_limit`;
CREATE TABLE `additive_food_limit` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `additive_id` BIGINT NOT NULL COMMENT '添加剂ID(关联additive_knowledge)',
  `food_category_code` VARCHAR(20) DEFAULT NULL COMMENT '食品分类号',
  `food_category_name` VARCHAR(300) DEFAULT NULL COMMENT '食品名称(冗余便于查询)',
  `max_dosage` VARCHAR(50) DEFAULT NULL COMMENT '最大使用量(g/kg或"按生产需要适量使用")',
  `function_in_use` VARCHAR(200) DEFAULT NULL COMMENT '在该用途下的功能',
  `is_inherited` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '是否为继承条目',
  `remark` TEXT COMMENT '备注',
  `note` TEXT COMMENT '说明',
  PRIMARY KEY (`id`),
  KEY `idx_additive_id` (`additive_id`),
  KEY `idx_food_code` (`food_category_code`),
  CONSTRAINT `fk_limit_additive` FOREIGN KEY (`additive_id`) REFERENCES `additive_knowledge` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='添加剂限量明细表';

-- ============================================================
-- 数据导入
-- ============================================================

-- 导入添加剂知识表(289条)
LOCK TABLES `additive_knowledge` WRITE;
UNLOCK TABLES;

-- 导入食品分类字典(388条)
LOCK TABLES `food_category` WRITE;
UNLOCK TABLES;

-- 导入限量明细表(32673条)
LOCK TABLES `additive_food_limit` WRITE;
UNLOCK TABLES;

SET FOREIGN_KEY_CHECKS = 1;

-- 完毕
